import { describe, it } from "vitest";

// Adopted readings where the specification leaves the observable contract open:
// - Rejections: the specification defines the CLI contract (non-zero exit, error
//   description on stderr). At the domain level a rejected scenario throws an
//   Error; the CLI translates that into the specified exit status and stderr.
// - A newcomer is a customer with 0 years with MHPCO. Unless stated otherwise a
//   quote is the customer's first contract, so its premium is
//   base premium + 10 % first insurance + 5 G processing fee.

describe("MHPCO claim office", () => {
  describe("quote: base premiums from the price list", () => {
    it.todo("empty item list -> premium 5 G (only the processing fee)");
    it.todo("sword -> 100 G base premium (newcomer premium 115 G)");
    it.todo("amulet -> 60 G base premium (newcomer premium 71 G)");
    it.todo("staff -> 80 G base premium (newcomer premium 93 G)");
    it.todo("potion -> 40 G base premium (newcomer premium 49 G)");
    it.todo("2 runes -> 50 G base premium (newcomer premium 60 G)");
    it.todo("3 runes -> 60 G base premium, block applies (newcomer premium 71 G)");
    it.todo("4 runes -> 100 G base premium, block requires exactly 3 (newcomer premium 115 G)");
    it.todo("7 runes -> 175 G base premium; calculation yields 197.5 G -> premium 198 G (rounded up)");
    it.todo("2 runes + 1 moonstone -> 75 G base premium, no block for different types (87.5 G -> premium 88 G)");
    it.todo("3 runes + 3 moonstones -> 120 G base premium, two separate blocks (newcomer premium 137 G)");
  });

  describe("quote: premium modifiers", () => {
    it.todo("newcomer with a cursed sword (steel, enchantment 3) -> premium 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
    it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies (100 + 30 + 10 + 5 = premium 145 G)");
    it.todo("cursed sword with exactly enchantment 5 -> both surcharges apply (100 + 50 + 30 + 10 + 5 = premium 195 G)");
    it.todo("sword with enchantment 4 -> no high-enchantment surcharge (premium 115 G)");
    it.todo("cursed sword with enchantment 4 -> only the curse surcharge applies (premium 165 G)");
    it.todo("cursed sword + plain amulet -> curse surcharge 50 G on the sword only: 210 G before policy-wide modifiers (+ 16 first insurance + 5 fee = premium 231 G)");
    it.todo("sword with enchantment 5 + plain amulet -> high-enchantment surcharge 30 G on the sword only (160 + 30 + 16 + 5 = premium 211 G)");
    it.todo("customer with exactly 2 years with MHPCO -> loyalty discount applies (sword: 100 - 20 + 10 + 5 = premium 95 G)");
    it.todo("customer with 1 year with MHPCO -> no loyalty discount (sword: premium 115 G)");
    it.todo("each quote after the customer's first gets the 15 % follow-up discount (newcomer, three sword quotes -> premiums 115 G, 100 G, 100 G)");
    it.todo("long-standing customer's second contract: 3 years, second quote, cursed sword (steel, enchantment 7) -> premium 160 G (first insurance surcharge still applies)");
    it.todo("intermediate amounts are kept as fractions: newcomer's second quote for a single rune -> 25 + 2.5 - 3.75 + 5 = 28.75 G -> premium 29 G");
    it.todo("quote with an unknown item type (broomstick) -> the scenario is rejected: throws an Error naming the unknown type");
  });

  describe("claim: reimbursement and deductible", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G (full reimbursement minus 100 G deductible), remaining cap 1600 G");
    it.todo("rune, damage 200 G -> payout 100 G (no special clause), remaining cap 400 G");
    it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)");
    it.todo("steel sword, enchantment 7, damage 1000 G -> payout 900 G (below the enchantment 8 threshold: full reimbursement minus deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (both clauses apply; the 50 % rule wins)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
    it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) -> payout 600 G (deductible applies once per damaged item)");
    it.todo("two swords both damaged (500 G each) -> payout 800 G (each damage entry has its own deductible)");
    it.todo("adopted reading: the n-th damage entry of a type refers to the n-th insured item of that type (swords with enchantment 9 and 3, 1000 G each -> payout 400 + 900 = 1300 G)");
    it.todo("adopted reading: a damage below the deductible pays nothing and does not reduce other payouts (sword 50 G + amulet 300 G -> payout 200 G)");
    it.todo("payout calculation that yields 350.5 G -> payout 350 G (rounded down; enchantment 9 sword, damage 901 G)");
    it.todo("intermediate payout amounts are kept as fractions: two enchantment 9 swords, 901 G each -> 350.5 + 350.5 = payout 701 G");
  });

  describe("claim: insurance sum and payout cap", () => {
    it.todo("two swords -> insurance sum 2000 G, cap 4000 G (one sword damaged 500 G -> payout 400 G, remaining cap 3600 G)");
    it.todo("sword and amulet -> insurance sum 1600 G, cap 3200 G (amulet damaged 300 G -> payout 200 G, remaining cap 3000 G)");
    it.todo("cursed sword -> cap 2000 G, premium modifiers do not raise the cap (damage 500 G -> payout 400 G, remaining cap 1600 G)");
    it.todo("sword and 3 runes (a block) -> insurance sum 1750 G, cap 3500 G (rune damaged 200 G -> payout 100 G, remaining cap 3400 G)");
    it.todo("staff -> insurance value 800 G, cap 1600 G (damage 300 G -> payout 200 G, remaining cap 1400 G)");
    it.todo("potion -> insurance value 400 G, cap 800 G (damage 300 G -> payout 200 G, remaining cap 600 G)");
    it.todo("moonstone -> insurance value 250 G, cap 500 G (damage 200 G -> payout 100 G, remaining cap 400 G)");
    it.todo("cap exhaustion: sword, two successive claims of 1500 G -> payout 1400 G / remaining cap 600 G, then payout 600 G / remaining cap 0 G");
    it.todo("claims against different policies deplete only their own cap (sword policy and amulet policy, one claim each)");
  });

  describe("claim: rejections", () => {
    it.todo("damage entry for an item that is not part of the policy (amulet damaged, only a sword insured) -> the whole claim is rejected: throws an Error");
    it.todo("damage entry with an unknown item type (broomstick) -> the whole claim is rejected: throws an Error");
    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) -> the whole claim is rejected: throws an Error");
    it.todo("damage entry with amount -200 -> the claim is rejected: throws an Error");
    it.todo("adopted reading: a claim whose policy index does not refer to an earlier quote step -> rejected: throws an Error");
  });
});

