export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = { op: "quote"; items: Item[] };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type QuoteResult = { premium: number };

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60 };
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
