export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80 };

export function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

