export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isInBlock(item: Item, items: Item[]): boolean {
  const alikeCount = items.filter((other) => other.type === item.type).length;
  return item.type === "rune" && alikeCount === BLOCK_SIZE;
}

function itemBasePremium(item: Item, items: Item[]): number {
  return isInBlock(item, items) ? BLOCK_BASE_PREMIUM / BLOCK_SIZE : BASE_PREMIUMS[item.type];
}

export function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + itemBasePremium(item, items), 0);
}

