input.content:
import { policyBasePremium, type Item } from "./price-list.js";

const PROCESSING_FEE = 5;
const CURSE_SURCHARGE_PERCENT = 50;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

function roundedInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

export function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const curseSurcharge = items.some((item) => item.cursed)
    ? (basePremium * CURSE_SURCHARGE_PERCENT) / PERCENT
    : 0;
  const firstInsuranceSurcharge = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
  return roundedInMHPCOsFavor(
    basePremium + curseSurcharge + firstInsuranceSurcharge + PROCESSING_FEE,
  );
}

