    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
  );
  return anyItemHighlyEnchanted ? percentOf(basePremium, HIGH_ENCHANTMENT_SURCHARGE_PERCENT) : 0;
}

