cat > src/premium.ts <<'EOF'
import { percentOf } from "./percent.js";
import { policyBasePremium, type Item } from "./price-list.js";
import { riskSurcharge } from "./risk-surcharge.js";

export type Customer = { yearsWithMHPCO: number };

const PROCESSING_FEE = 5;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

function roundedInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

export function quotePremium(customer: Customer, items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_YEARS ? percentOf(basePremium, LOYALTY_DISCOUNT_PERCENT) : 0;
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundedInMHPCOsFavor(
    basePremium +
      riskSurcharge(items) -
      loyaltyDiscount +
      firstInsuranceSurcharge +
      PROCESSING_FEE,
  );
}
EOF
cat > src/claim-office.ts <<'EOF'
import { quotePremium, type Customer } from "./premium.js";
import type { Item } from "./price-list.js";

export type QuoteStep = { op: "quote"; items: Item[] };

export type Scenario = {
  customer: Customer;
  steps: QuoteStep[];
};

export type QuoteResult = { premium: number };

export function processScenario(scenario: Scenario): { results: QuoteResult[] } {
  const { customer, steps } = scenario;
  return { results: steps.map((step) => ({ premium: quotePremium(customer, step.items) })) };
}
EOF
