cat > src/claim.ts <<'EOF'
import { percentOf } from "./percent.js";
import { insuranceSum, type Item } from "./price-list.js";

export type Damage = { itemType: string; amount: number };

export type Settlement = { payout: number; remainingCap: number };

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;
const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
const REDUCED_REIMBURSEMENT_PERCENT = 50;

function reimbursement(damage: Damage, insuredItems: Item[]): number {
  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
  const enchantment = damagedItem?.enchantment ?? 0;
  return enchantment >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL
    ? percentOf(damage.amount, REDUCED_REIMBURSEMENT_PERCENT)
    : damage.amount;
}

export function settleClaim(insuredItems: Item[], damages: Damage[]): Settlement {
  const reimbursementTotal = damages.reduce(
    (sum, damage) => sum + reimbursement(damage, insuredItems),
    0,
  );
  const payout = reimbursementTotal - DEDUCTIBLE;
  const cap = CAP_FACTOR * insuranceSum(insuredItems);
  return { payout, remainingCap: cap - payout };
}
EOF
