export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = { sword: 1000, amulet: 600 };
const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_INSURANCE_VALUE = 250;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function areAlike(component: Item, other: Item): boolean {
  return component.type === other.type;
}

function formsBlock(component: Item, items: Item[]): boolean {
  const alikeCount = items.filter((other) => areAlike(component, other)).length;
  return alikeCount === BLOCK_SIZE;
}

function componentBasePremium(component: Item, items: Item[]): number {
  return formsBlock(component, items) ? BLOCK_BASE_PREMIUM / BLOCK_SIZE : COMPONENT_BASE_PREMIUM;
}

function mainItemBasePremium(item: Item): number {
  if (!Object.hasOwn(MAIN_ITEM_BASE_PREMIUMS, item.type)) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return MAIN_ITEM_BASE_PREMIUMS[item.type];
}

export function itemBasePremium(item: Item, items: Item[]): number {
  return isComponent(item) ? componentBasePremium(item, items) : mainItemBasePremium(item);
}

export function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + itemBasePremium(item, items), 0);
}

function insuranceValue(item: Item): number {
  return isComponent(item) ? COMPONENT_INSURANCE_VALUE : MAIN_ITEM_INSURANCE_VALUES[item.type];
}

export function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValue(item), 0);
}

