  const { customer, steps } = scenario;
  const policies: PoliciesByQuoteStep = new Map();
  return {
    results: steps.map((step, stepIndex) =>
      step.op === "quote"
        ? processQuote(customer, step, stepIndex, policies)
        : processClaim(step, policies),
    ),
  };
}
